import React from 'react';

const TripleHelice = () => {
    return (
        <div className="triple-helice">
            <h2>Modelo de Triple Hélice de Innovación</h2>
            <p>
                La propuesta incorpora el modelo de triple hélice de innovación, que promueve la colaboración entre academia, gobierno y sector privado para generar un impacto social significativo.
            </p>
            <h3>Academia</h3>
            <p>
                Las universidades y centros educativos desempeñan un papel fundamental en la investigación histórica, la elaboración de contenido educativo y la validación académica de la información difundida.
            </p>
            <h3>Gobierno</h3>
            <p>
                Instituciones públicas como el Ministerio de Educación Pública y el Tribunal Supremo de Elecciones pueden colaborar en la difusión del contenido, el fortalecimiento de programas de educación cívica y la incorporación de materiales en espacios formativos.
            </p>
            <h3>Sector Privado</h3>
            <p>
                Los medios de comunicación, plataformas digitales y productoras audiovisuales pueden contribuir a la producción de contenido y a su difusión masiva, utilizando formatos atractivos y accesibles para la población meta.
            </p>
        </div>
    );
};

export default TripleHelice;
